-- Derived indexes (rebuilt on demand; cheap). byType maps ANY brand full type -> brand; kindOf maps full type -> "pack"|"single"|"carton".
function TC.rebuildIndex()
  TC.byType, TC.kindOf, TC.BrandIndex = {}, {}, {}
  for _, b in ipairs(TC.Brands) do
    for _, kind in ipairs({ "pack", "single", "carton" }) do
      local full = b[kind]
      if full then TC.byType[full] = b; TC.kindOf[full] = kind; TC.BrandIndex[full] = kind end
    end
    -- flatten extras into arrays once: {{stat="STRESS", delta=-0.03}, ...}; per-tick code must not allocate
    local function flat(maps)
      local acc, out = {}, {}
      for i = 1, 2 do
        local m = maps[i]
        if type(m) == "table" then for k, v in pairs(m) do if type(v) == "number" then acc[k] = (acc[k] or 0) + v end end end
      end
      for k, v in pairs(acc) do out[#out + 1] = { stat = k, delta = v } end
      table.sort(out, function(x, y) return x.stat < y.stat end)   -- deterministic order
      return out
    end
    b._xs = flat({ b.extras, b.extrasSmoker })
    b._xn = flat({ b.extras, b.extrasNonSmoker })
  end
end
TC.rebuildIndex()
